/* 语言 / Language. Every Chinese UI string in js*.js is tagged TR`…`: zh returns it as written,
   en looks the whole template (holes written as {0},{1}…) up in I18N_EN. head.html is translated once at start. */
var LANG=(()=>{try{const s=localStorage.getItem('ark-lang');if(s==='zh'||s==='en')return s;}catch(e){}return /^zh/i.test(navigator.language||'')?'zh':'en';})();
const _LC=new WeakMap();
function Lv(x){if(LANG!=='en'||typeof x!=='string')return x;const e=I18N_EN[x];return e!=null?e:x;}
function TR(strs,...v){
  if(LANG!=='en'){if(!v.length)return strs[0];let s=strs[0];for(let i=0;i<v.length;i++)s+=v[i]+strs[i+1];return s;}
  let t=_LC.get(strs);
  if(t===undefined){let k=strs[0];for(let i=0;i<v.length;i++)k+='{'+i+'}'+strs[i+1];t=I18N_EN[k];if(t==null)t=null;_LC.set(strs,t);}
  if(t===null){let s=strs[0];for(let i=0;i<v.length;i++)s+=v[i]+strs[i+1];return s;}
  return v.length?t.replace(/\{(\d+)\}/g,(m,i)=>{const x=v[+i];return x==null?'':Lv(x);}):t;
}
function setLang(l){try{localStorage.setItem('ark-lang',l);}catch(e){}}
/* switching language reloads the page; inside a tank it saves first and reopens the same tank */
function switchLang(l){if(l!=='zh'&&l!=='en'||l===LANG)return;setLang(l);
  if(!document.getElementById('home')){try{saveNow();sessionStorage.setItem('ark-resume',MK);}catch(e){}}
  location.reload();}
/* translate the static DOM from head.html: text nodes plus title / aria-label / placeholder / alt / meta content */
const I18N_HAN=/[　-〿一-鿿＀-￯]/;
function i18nDOM(root){if(LANG!=='en')return;
  document.documentElement.lang='en';if(document.title)document.title=Lv(document.title.trim());
  const w=document.createTreeWalker(root||document.body,NodeFilter.SHOW_TEXT);let n;
  while(n=w.nextNode()){const raw=n.nodeValue;if(!I18N_HAN.test(raw))continue;const t=raw.replace(/\s+/g,' ').trim();const e=I18N_EN[t];
    if(e!=null){const m=raw.match(/^\s*/)[0],z=raw.match(/\s*$/)[0];n.nodeValue=m+e+z;}}
  (root||document).querySelectorAll('[title],[aria-label],[placeholder],[alt],meta[content]').forEach(el=>{for(const a of ['title','aria-label','placeholder','alt','content']){const v=el.getAttribute(a);if(v&&I18N_HAN.test(v)){const e=I18N_EN[v.trim()];if(e!=null)el.setAttribute(a,e);}}});}
